function fit_kundur_e123_effective_params3()
pf_init_paths; c=cases.case_kundur_two_area_classical(); pf=pfsolver.powerflow_newton_raphson(c,struct('plot_results',false,'verbose',false,'max_iter',50,'tolerance',1e-8,'enforce_q_limits',false)); baseM=c.machines; ref=[-0.111 3.430 0.032; -0.492 6.820 0.072; -0.506 7.020 0.072];
p0=log([0.556 0.556 0.0358 0.0478 1.014 1.011]); opts=optimset('Display','iter','MaxIter',180,'MaxFunEvals',360,'TolX',2e-4,'TolFun',1e-9); [p,J]=fminsearch(@(p)cost(p,pf,baseM,ref),p0,opts); v=exp(p); fprintf('J=%g Tpq12=%.6f Tpq34=%.6f Tppd=%.6f Tppq=%.6f H12=%.6f H34=%.6f\n',J,v); show(v,pf,baseM,ref);
end
function J=cost(p,pf,baseM,ref); v=exp(p); if any(v<0)||v(1)<.05||v(1)>2||v(2)<.05||v(2)>2||v(3)<.002||v(3)>.2||v(4)<.002||v(4)>.2||v(5)<.7||v(5)>1.5||v(6)<.7||v(6)>1.5; J=1e6; return; end; try; m=modes(v,pf,baseM); J=0; for k=1:3; scale=[abs(ref(k,1)) ref(k,2) ref(k,3)]; w=[1 1 1]; J=J+sum(w.*((m(k,:)-ref(k,:))./scale).^2); end; catch; J=1e6; end; end
function m=modes(v,pf,baseM); M=baseM; M.time_constants.Tpq0=v(1); % global struct only, cannot per-unit; emulate area split impossible with scalar TC
M.time_constants.Tppd0=v(3); M.time_constants.Tppq0=v(4); for kk=1:2; M.units(kk).H=baseM.units(kk).H*v(5); end; for kk=3:4; M.units(kk).H=baseM.units(kk).H*v(6); end; ssa=stability.kundur_ex126_kundur_ssa('pf',pf,'options',struct('load_model','cc_p_cz_q','machine_override',M)); lam=ssa.eigenvalues(:); osc=lam(abs(imag(lam))>.1&real(lam)<0&imag(lam)>0); [~,idx]=sort(abs(imag(osc))); osc=osc(idx); m=zeros(3,3); for k=1:3; m(k,:)=[real(osc(k)) imag(osc(k)) -real(osc(k))/abs(osc(k))]; end; end
function show(v,pf,baseM,ref); m=modes(v,pf,baseM); for k=1:3; fprintf('m%d %.6f+j%.6f z=%.6f ferr=%.3f zerr=%.3f reerr=%.3f\n',k,m(k,1),m(k,2),m(k,3),abs(m(k,2)-ref(k,2))/ref(k,2)*100,abs(m(k,3)-ref(k,3))/ref(k,3)*100,abs(m(k,1)-ref(k,1))/abs(ref(k,1))*100); end; end
